// Hindi for sages/agastya.js — keys are HI.hash(<Telugu string>). Written by tools/hi_write.js.
HI.add({
 "18853890": "महाभारत का आश्वमेधिक पर्व बताता है कि एक बार अगस्त्य ने बारह साल चलने वाला एक यज्ञ शुरू किया। उस दौरान इंद्र ने बारिश नहीं भेजी। बाकी ऋषि चिंतित हो गए कि यज्ञ आगे नहीं चल पाएगा। अगस्त्य ने कहा: “अगर इंद्र बारह साल तक बारिश नहीं करेंगे, तो मैं खुद इंद्र बन जाऊँगा। मैं बारिश करूँगा, और सबके लिए अन्न पैदा करूँगा।” यह सुनकर इंद्र का घमंड उतर गया। उन्होंने बारिश भेजी, यज्ञ में आए, और ऋषि से मेल कर लिया।",
 "23500726": "ऋग्वेद के तूफ़ान के देवता — युवा भाइयों की एक चमकती टोली, जो इंद्र के साथ चलती है।",
 "27411945": "नहुष अच्छे थे, इसलिए स्वर्ग के लिए चुने गए, और सत्ता ने उन्हें घमंडी बना दिया, इसलिए गिरे। तुम्हें क्या लगता है, सत्ता लोगों को क्यों बदल देती है? कोई इससे अपने को कैसे बचा सकता है?",
 "31666312": "उन्होंने ऋषियों से अपनी पालकी उठवाई और अगस्त्य को लात मारी, जिन्होंने उन्हें साँप बन जाने का श्राप दिया।",
 "43455471": "आदित्य हृदयम्",
 "44456193": "विदर्भ के एक राजा, जो स्वर्ग तो गए पर जिन्होंने कभी अन्न-दान नहीं किया था; अगस्त्य ने उन्हें उनकी अजीब भूख से छुटकारा दिलाया।",
 "48561053": "अगस्त्य और लोपामुद्रा के पुत्र, जो वेद पढ़ते हुए पैदा हुए। वे अपने पिता की अग्नि के लिए लकड़ियाँ लाते थे, इसलिए उनका नाम इध्मवाह पड़ा।",
 "98776564": "युद्ध के बाद, जब अयोध्या में राम का राज्याभिषेक हुआ, तो हर दिशा से बड़े-बड़े ऋषि उन्हें आशीर्वाद देने आए, और अगस्त्य उनकी ओर से बोले। राम ने उनसे उन शत्रुओं के बारे में पूछा जिनसे वे लड़े थे: रावण कौन था? राक्षस कहाँ से आए? इंद्रजीत इतना बलवान कैसे था? और अगस्त्य ने उन्हें सब बताया — ये ही कथाएँ उत्तर कांड के पहले भाग में हैं।",
 "f3efcd6b": "घड़े से जन्म",
 "11b23960": "सभी महान ऋषियों में अगस्त्य ने सबसे अचरज भरे काम किए। उन्होंने एक राक्षस को पूरा निगलकर पचा लिया। उन्होंने पूरा समुद्र पी लिया। उन्होंने एक पर्वत से झुकने को कहा, और वह आज तक झुका हुआ है। उन्होंने राम को वे अस्त्र दिए जिनसे लंका का युद्ध जीता गया, और युद्ध के मैदान में ही राम को सूर्य का एक स्तोत्र सिखाया। और वे दक्षिण की ओर चले, विंध्य की पहाड़ियाँ पार कीं, और दक्षिण की धरती को हमेशा के लिए अपना घर बना लिया।",
 "150df0ae": "फिर भी उनका जन्म सबसे अनोखा था। साधारण तरह से उनकी कोई माँ नहीं थी, और वे किसी गर्भ से नहीं, बल्कि मिट्टी के एक घड़े से पैदा हुए। इसीलिए पूरे भारत में उन्हें कुंभसंभव और कलशज कहा जाता है — “घड़े से जन्मे।”",
 "1463492f": "तेलुगु घरों में अगस्त्य को अक्सर बस कुंभमुनि कहा जाता है — “घड़े वाले मुनि।”",
 "2b94f443": "मित्र और वरुण का यज्ञ",
 "0662045d": "कथा खुद ऋग्वेद में, वसिष्ठ के परिवार के एक सूक्त (7.33) में शुरू होती है। एक बार दो महान देवता {mitravaruna|मित्र और वरुण} एक लंबे यज्ञ में साथ बैठे थे। वहाँ अप्सरा {urvashi|उर्वशी} आई, और उसे देखकर दोनों देवता अपने को सँभाल न सके। उनका तेज — उनका दिव्य बीज — उनसे गिर पड़ा। उसे यज्ञ में काम आने वाले एक घड़े, यानी कुंभ, में इकट्ठा करके रख दिया गया।",
 "d89d1403": "उसी एक घड़े से दो ऋषि प्रकट हुए। सूक्त कहता है कि उसके बीच से “मान” उठे — और पुराने टीकाकार बताते हैं कि मान ही अगस्त्य हैं। दूसरे थे {vasishtha|वसिष्ठ}, जिनका वहाँ दूसरी बार जन्म हुआ। इस तरह सूर्यवंश की कथा के दो सबसे बड़े ऋषि भाई हैं, और दोनों को मैत्रावरुणि, यानी “मित्र और वरुण के पुत्र”, कहा जाता है।",
 "dca58525": "वसिष्ठ को दूसरा जन्म क्यों लेना पड़ा — निमि का श्राप",
 "94a78ce6": "ग्रंथ इसे कैसे बताते हैं",
 "894c9ff4": "बृहद्देवता, जो वैदिक सूक्तों और उनके द्रष्टा ऋषियों के बारे में एक पुरानी पुस्तक है, यह जन्म और विस्तार से बताती है: बीज एक से ज़्यादा जगह गिरा, और घड़े से अगस्त्य निकले, जबकि वसिष्ठ अलग से प्रकट हुए। रामायण का उत्तर कांड भी, जहाँ राम खुद लक्ष्मण को यह कथा सुनाते हैं, अगस्त्य का जन्म वसिष्ठ के साथ मित्र और वरुण के घड़े में ही बताता है। पुराण इसे थोड़े-बहुत अंतर के साथ दोहराते हैं। मुख्य बात पर सब सहमत हैं: अगस्त्य और वसिष्ठ का एक ही अद्भुत मूल है।",
 "7caa952d": "बाद की परंपरा जोड़ती है कि अगस्त्य बहुत छोटे क़द के थे — शरीर में छोटे, पर शक्ति में अपार। “मान” यानी “माप” नाम का अर्थ कभी-कभी इसी तरह समझाया जाता है। यह एक सुंदर विरोधाभास है जो उनकी सारी कथाओं में चलता है: सबसे छोटे ऋषि सबसे बड़े काम करते हैं।",
 "1288a4b7": "अगस्त्य नाम का एक पारंपरिक अर्थ: *अग* यानी “जो हिलता नहीं” — पर्वत — और अगस्त्य यानी “जिसने पर्वत को रोक दिया।” अध्याय 6 में तुम देखोगे क्यों।",
 "4fa73d53": "कई ग्रंथों में एक जीवन",
 "3487f05c": "कोई एक ग्रंथ अगस्त्य का पूरा जीवन नहीं बताता। ऋग्वेद में उनके सूक्त और उनकी पत्नी {lopamudra|लोपामुद्रा} के वचन हैं। महाभारत, पांडवों को तीर्थयात्रा कराने वाले ऋषि लोमश के मुँह से, उनके विवाह, राक्षस वातापि, विंध्य पर्वत और समुद्र पीने की कथा बताता है। रामायण राम से उनकी भेंट बताती है। पुराण और तमिल परंपरा दक्षिण में उनके जीवन की बात करते हैं। यह कथा उन्हें क्रम से जोड़ती है, और बताती है कि कौन-सी बात किस ग्रंथ में है।",
 "c6726396": "और सर्दियों की किसी साफ़ रात को दक्षिण के आकाश में देखो: क्षितिज के पास नीचे कैनोपस चमकता है, जो पूरे आकाश का दूसरा सबसे चमकीला तारा है। भारत में उस तारे को हमेशा से अगस्त्य कहा जाता है।",
 "6f397d8e": "ऋग्वेद 7.33.10–13 (घड़े से वसिष्ठ और “मान” का जन्म, सायण की टीका के साथ, जो मान को अगस्त्य बताती है); बृहद्देवता (अगस्त्य और वसिष्ठ के जन्म का वर्णन); वाल्मीकि रामायण, उत्तर कांड (निमि और वसिष्ठ की कथा, राम के मुँह से)। बीज कैसे गिरा, इसकी छोटी-छोटी बातों में ग्रंथों में अंतर है।",
 "741cf2fd": "अगस्त्य {mitravaruna|मित्र और वरुण} के घड़े से, वसिष्ठ के साथ पैदा हुए।",
 "d9d116ec": "इसलिए उन्हें कुंभसंभव, कलशज और मैत्रावरुणि कहा जाता है; ऋग्वेद उन्हें मान कहता है।",
 "fbd66a37": "शरीर में छोटे, पर उन्होंने सबसे बड़े काम किए — और कैनोपस तारा उनका नाम धारण करता है।",
 "caa83a2d": "अगस्त्य छोटे थे पर उन्होंने बहुत बड़े काम किए। तुम्हें क्या लगता है, कथाएँ सबसे शक्तिशाली ऋषि को सबसे छोटा क्यों दिखाना पसंद करती हैं?",
 "da2a2513": "ऋग्वेद के द्रष्टा — इंद्र और मरुत",
 "5d611dee": "राक्षसों और समुद्रों की कथाओं से पहले, अगस्त्य सबसे पहले एक ऋषि थे — एक द्रष्टा, जिन्होंने गहरे ध्यान में वैदिक सूक्तों को “देखा” और संसार को दिया। ऋग्वेद के पहले मंडल में, सूक्त 165 से 191 तक की एक लंबी कड़ी अगस्त्य मैत्रावरुणि और उनके परिवार की है। ये {indra|इंद्र}, {maruts|मरुतों}, {agni|अग्नि}, अश्विनी कुमारों, द्युलोक और पृथ्वी — और खुद अन्न की भी स्तुति करते हैं।",
 "b53e9469": "सूक्त 1.187 *पितु* — अन्न, पोषण — की स्तुति का सूक्त है। अगस्त्य वे द्रष्टा हैं जिन्होंने अन्न को देवता मानकर पूजा। यह बात याद रखना, जब पढ़ोगे कि उन्होंने राक्षस वातापि को कैसे “खा” लिया।",
 "bd291c7d": "एक आहुति पर झगड़ा",
 "56f50344": "अगस्त्य के कुछ सूक्तों में एक छोटा-सा नाटक छिपा है। इंद्र देवताओं के राजा हैं, और मरुत, तूफ़ान के देवता, उनके साथी हैं जो उनके साथ युद्ध में जाते हैं। सूक्त 1.165 में इंद्र और मरुत आपस में बात करते हैं, और हर कोई बड़े कामों की महिमा अपनी बताता है। इंद्र कहते हैं कि शत्रु को उन्होंने अकेले मारा; मरुत जवाब देते हैं कि वे उनके साथ खड़े थे। अंत में इंद्र उनकी प्रशंसा करते हैं, और अगस्त्य अपना सूक्त दोनों को अर्पित करते हैं।",
 "14fa3529": "सूक्त 1.170 में यह नाटक और तीखा हो जाता है। अगस्त्य ने एक आहुति तैयार की थी, और इंद्र को लगा कि वह उन्हीं की होनी चाहिए थी, मरुतों के साथ बाँटी नहीं जानी चाहिए थी। सूक्त इंद्र के बेचैन शब्दों से शुरू होता है — कि आज या कल का कोई भरोसा नहीं, और मनुष्यों का मन भटकता रहता है। अगस्त्य उन्हें प्यार से जवाब देते हैं: इंद्र उन्हें नुक़सान क्यों पहुँचाएँगे? मरुत तो उनके अपने भाई हैं। वे उनके साथ शांति से बाँट लें।",
 "afb56bc5": "अगले सूक्त, 1.171 में, अगस्त्य मरुतों की ओर मुड़ते हैं और उनसे भी अपना क्रोध छोड़ने को कहते हैं, क्योंकि वे इंद्र की शक्ति से डर गए थे। इस तरह इन थोड़े-से मंत्रों में हम ऋषि को घमंडी भाइयों के बीच शांति कराने वाले के रूप में देखते हैं — देवताओं के राजा के सामने अपनी बात पर डटे हुए, और फिर भी दोनों पक्षों को फिर से साथ लाते हुए।",
 "96760b2c": "हर ज़रूरत के लिए सूक्त",
 "d1c6a3fd": "अगस्त्य के सारे सूक्त बड़े देवताओं और बड़े युद्धों के लिए नहीं हैं। उनके समूह का आख़िरी सूक्त, 1.191, ज़हर के विरुद्ध एक मंत्र है — छोटे, छिपे हुए जीवों के काटने और डंक के विरुद्ध, जो घास में और पत्थरों के नीचे रेंगते हैं। यह सूर्य को पुकारता है कि वे ज़हर को जला दें। पुराने वैदिक संसार में द्रष्टा आम लोगों के जीवन का रक्षक भी होता था।",
 "21a3a92e": "सूक्त 1.179 फिर अलग है: यह अगस्त्य और उनकी पत्नी लोपामुद्रा के बीच एक संवाद है, और यह जितना उनका है उतना ही लोपामुद्रा का भी। इसे हम अध्याय 4 में सुनेंगे, जब उनके साथ के जीवन की बात आएगी।",
 "7868e247": "अगस्त्य गोत्र-ऋषियों में से एक हैं। कई परिवार आज भी अपने प्रवर में — पूर्वज ऋषियों की उस सूची में जो अनुष्ठानों में पढ़ी जाती है — उनका नाम लेते हैं।",
 "b8537a7d": "ऋग्वेद, मंडल 1, सूक्त 165–191, जो अगस्त्य मैत्रावरुणि के माने जाते हैं (सूक्त 1.179 लोपामुद्रा के साथ साझा)। इंद्र, मरुतों और अगस्त्य का संवाद: 1.165, 1.170 और 1.171। अन्न: 1.187। ज़हर के विरुद्ध: 1.191। 1.170 के पीछे की कथा पुरानी टीकाओं और बृहद्देवता में समझाई गई है।",
 "5d85276f": "अगस्त्य ऋग्वेद के सूक्त 1.165–191 के द्रष्टा हैं।",
 "707b09f9": "उन्होंने एक आहुति को लेकर {indra|इंद्र} और {maruts|मरुतों} के बीच सुलह कराई।",
 "fa8da7b1": "उनके सूक्त अन्न तक की स्तुति करते हैं, और लोगों को ज़हर से बचाते हैं।",
 "9e512216": "अगस्त्य ने इंद्र से कहा, “मरुत तुम्हारे भाई हैं।” जब तुम्हारे दो प्यारे लोग इस पर झगड़ें कि श्रेय किसे मिले, तो उन्हें साथ लाने के लिए तुम क्या कह सकते हो?",
 "93a7ee0e": "गड्ढे में लटके पितर — लोपामुद्रा की रचना",
 "3fab604c": "इन दिनों के बहुत बाद, जब पांडव वन में रह रहे थे, ऋषि {lomasha|लोमश} उन्हें भारत के पवित्र स्थानों की तीर्थयात्रा पर ले गए। हर जगह वे उसकी कथा सुनाते। जब वे अगस्त्य के एक आश्रम पर पहुँचे, तो {yudhishthira|युधिष्ठिर} ने उस महान ऋषि के बारे में पूछा, और लोमश ने अगस्त्य के विवाह की कथा शुरू की।",
 "c6356d4a": "अगस्त्य बहुत लंबे समय तक ब्रह्मचारी रहे थे — एक ब्रह्मचारी विद्यार्थी और तपस्वी। उनके पास न घर था, न पत्नी, न धन — बस उनकी तपस्या, उनकी अग्नि और उनका वेद। उन्हें नहीं लगता था कि उन्हें और किसी चीज़ की ज़रूरत है।",
 "729fffe2": "उल्टे लटके हुए",
 "4d0f2689": "एक दिन घूमते-घूमते अगस्त्य ने एक भयानक दृश्य देखा। एक गहरे गड्ढे में कुछ लोग सिर नीचे करके लटके हुए थे, लगभग किसी सहारे के बिना। उन्होंने पूछा कि वे कौन हैं। उन्होंने कहा: “हम तुम्हारे ही पूर्वज, तुम्हारे पितर हैं। हम यहाँ इसलिए लटके हैं क्योंकि हमारा वंश ख़त्म होने वाला है। अगर तुम्हारा कोई पुत्र नहीं हुआ, तो हमें श्राद्ध देने वाला कोई नहीं रहेगा, और हम अंधकार में गिर जाएँगे। बेटा, विवाह करो और पुत्र पाओ — तब हम बच जाएँगे।”",
 "4908f506": "अगस्त्य का मन पिघल गया। “मैं ऐसा करूँगा,” उन्होंने वचन दिया। “दुखी मत होइए।” एक महान तपस्वी की तपस्या उन लोगों के प्रति उसका कर्तव्य ख़त्म नहीं कर देती जो उससे पहले आए — महाभारत इस कथा से यही सीख निकालता है।",
 "6ad3cf01": "महाभारत लगभग यही कथा एक और ऋषि, जरत्कारु, के बारे में भी बताता है, जिन्होंने भी अपने पितरों को एक गड्ढे में लटके देखा और उनके लिए विवाह किया। उनके पुत्र आस्तीक ने आगे चलकर नागों को बचाया।",
 "dd96ce65": "सारी सुंदरता से बनी दुल्हन",
 "ed812788": "पर उन्हें ऐसी पत्नी कहाँ मिलती जो उनके जैसे ऋषि का जीवन बाँट सके? उन्होंने ढूँढा, पर कोई स्त्री उन्हें योग्य नहीं लगी। तब अगस्त्य ने वह किया जो सिर्फ़ वही कर सकते थे। हर प्राणी का सबसे अच्छा, सबसे सुंदर अंश लेकर, हर तरह के जीव से एक, उन्होंने अपनी शक्ति से एक संपूर्ण कन्या बनाई।",
 "732dc1b6": "उस समय विदर्भ के राजा संतान की इच्छा से तपस्या कर रहे थे। अगस्त्य ने उस कन्या को ऐसे रखा कि वह राजा की रानी से उनकी बेटी बनकर पैदा हुई। क्योंकि हर प्राणी की विशेष सुंदरता ले ली गई थी — लोप, यानी “खो जाना” — और उसमें इकट्ठा की गई थी, इसलिए उसका नाम लोपामुद्रा रखा गया।",
 "99be0732": "वह लौ की तरह चमकती हुई बड़ी हुई, और सौ सखियाँ उसकी सेवा करती थीं। राजकुमारों ने उसकी सुंदरता के बारे में सुना, पर किसी ने उसका हाथ माँगने की हिम्मत नहीं की — सबको डर था कि महान अगस्त्य की नज़र उस पर है।",
 "cf0aa0ab": "“पिताजी, मुझे उन्हें दे दीजिए”",
 "49f48d66": "जब वह विवाह योग्य हुई, तो अगस्त्य विदर्भ के राजा के पास आए और लोपामुद्रा को अपनी पत्नी के रूप में माँगा। राजा पर जैसे वज्र गिर पड़ा। वे महल में पली अपनी कोमल बेटी को जटाधारी, बिना किसी संपत्ति वाले वनवासी ऋषि को कैसे दे दें? पर अगर वे मना करते, तो ऋषि का श्राप उनके राज्य को जला सकता था। वे और रानी रोते हुए अपनी बेटी के पास गए।",
 "c242801b": "लोपामुद्रा ने उनका दुख देखा और शांति से कहा: “पिताजी, मेरे कारण दुखी मत होइए। मुझे अगस्त्य को दे दीजिए, और अपने को बचा लीजिए।” इस तरह उसका विवाह ऋषि से हो गया। उसने तुरंत अपने क़ीमती रेशमी कपड़े और गहने उतार दिए, और अपने पति की तरह वल्कल और मृगचर्म पहन लिए। वह उनके साथ गंगाद्वार गई, जहाँ गंगा पहाड़ों से निकलती हैं — आज का हरिद्वार — और वहाँ उसने प्रेम से उनकी सेवा की और उनके साथ तपस्विनी बनकर रही।",
 "7566ad3c": "एक कठिन बात, सीधे शब्दों में: लोपामुद्रा को अगस्त्य की पत्नी बनाने के लिए ही रचा गया और एक परिवार में रखा गया, और उसके माता-पिता ने डर के कारण हाँ की। महाभारत यह बात छिपाता नहीं। पर यह भी दिखाता है कि जाने का फ़ैसला आख़िर में उसका अपना था — और अगले अध्याय में वह अपनी शर्तें रखती है।",
 "6cbe6b96": "महाभारत, वन पर्व, तीर्थयात्रा पर्व — युधिष्ठिर को लोमश का अगस्त्य-वृत्तांत (गड्ढे में पितर, लोपामुद्रा की रचना, विदर्भ में उसका जन्म और उसका विवाह)। जरत्कारु की कथा: महाभारत, आदि पर्व, आस्तीक पर्व।",
 "ac342ad2": "अगस्त्य ने अपने पितरों को एक गड्ढे में लटके देखा और विवाह करके पुत्र पाने का वचन दिया।",
 "ebb9554e": "उन्होंने सभी प्राणियों की सुंदरता से {lopamudra|लोपामुद्रा} को बनाया; वह विदर्भ की राजकुमारी के रूप में पैदा हुई।",
 "4269c300": "उसने उनके साथ जाना चुना, अपने गहने छोड़ दिए, और गंगाद्वार में तपस्विनी बनकर रही।",
 "3d52aaf0": "लोपामुद्रा ने कहा, “मुझे उन्हें दे दीजिए, और अपने को बचा लीजिए।” क्या वह बहादुरी दिखा रही थी, या अपना बलिदान दे रही थी? क्या दोनों एक साथ हो सकते हैं?",
 "9ce2f007": "लोपामुद्रा की इच्छा और तीन ईमानदार राजा",
 "944ad5ef": "गंगाद्वार में कई साल बीत गए। एक दिन अगस्त्य ने {lopamudra|लोपामुद्रा} को स्नान करके लौटते देखा, अपनी ही तपस्या के तेज से चमकती हुई, और उनका मन प्रेम से भर गया। उन्होंने उसे बुलाया और पत्नी के रूप में अपने पास आने को कहा, ताकि उन्हें वह पुत्र मिले जिसके लिए उनके पितर तरस रहे थे।",
 "00ff79f3": "लोपामुद्रा ने हाथ जोड़े। वह शर्मीली थी, पर उसने साफ़-साफ़ कहा: “पति संतान के लिए पत्नी से विवाह करता है — यह मैं जानती हूँ। पर मेरी एक इच्छा है। मेरे पास वैसे पलंग पर आइए जैसा मेरे पिता के महल में मेरा था। मुझे वे दिव्य गहने पहनने दीजिए जो मैं कभी पहनती थी, और आप भी मालाएँ और सुंदर वस्त्र पहनिए। मैं इन वल्कल के चिथड़ों में, अग्नि की राख से सनी हुई, आपके पास नहीं आऊँगी। तपस्वी का वस्त्र पवित्र होता है; उसे इस तरह मैला नहीं करना चाहिए।”",
 "4b4b3174": "किसी को हानि पहुँचाए बिना धन",
 "7c3d7ddd": "अगस्त्य ने कहा: “देवी, मेरे पास तुम्हारे पिता जैसा कोई धन नहीं है।” उसने जवाब दिया: “अपनी तपस्या से आप पल भर में संसार का सारा धन यहाँ ला सकते हैं।” “सच है,” उन्होंने कहा, “पर इससे मेरी तपस्या व्यर्थ हो जाएगी। कोई और रास्ता बताओ।” और उसने कहा: “तो मैं नहीं चाहती कि आपकी तपस्या व्यर्थ हो। धन किसी सही तरीक़े से पाइए, और जो धर्म है वही कीजिए।”",
 "b84fe3a7": "तो महान ऋषि राजाओं से माँगने निकले। पहले वे राजा {shrutarvan|श्रुतर्वा} के पास आए, जिन्होंने हर तरह से उनका आदर-सत्कार किया और पूछा कि उन्हें क्या चाहिए। “मुझे धन दो,” अगस्त्य ने कहा, “पर सिर्फ़ उतना, जितना तुम किसी और प्राणी को हानि पहुँचाए बिना दे सको।” राजा ने उन्हें अपना हिसाब दिखाया: आने वाला हर सिक्का पहले ही अपने सही काम में ख़र्च हो चुका था। अगस्त्य ने देखा कि कुछ भी लेने का मतलब किसी और से छीनना होगा। उन्होंने इनकार कर दिया।",
 "dbe947e6": "श्रुतर्वा उनके साथ हो लिए, और दोनों राजा {bradhnashva|ब्रध्नाश्व} के पास गए। वहाँ भी वही हुआ: आय ख़र्च के बराबर, बचा कुछ नहीं। फिर तीनों इक्ष्वाकु वंश के पुरुकुत्स के पुत्र {trasadasyu|त्रसदस्यु} के पास गए — और फिर से हिसाब ठीक बराबर निकला। तीन राजा, और किसी के पास भी प्रजा से निचोड़ा हुआ छिपा धन नहीं था। ऋषि किसी और का एक सिक्का भी नहीं लेते।",
 "c020d715": "आख़िर में राजाओं ने कहा: “इल्वल नाम का एक दानव है, जो मणिमती में रहता है। वह धरती का सबसे धनी प्राणी है। चलो, उसके पास चलें।” और वे साथ-साथ चल पड़े — संसार के सबसे ख़तरनाक मेज़बान के पास।",
 "83fb5049": "लोपामुद्रा के अपने शब्द — ऋग्वेद 1.179",
 "89408a09": "ऋग्वेद में इस विवाह की एक बहुत पुरानी याद है — छह मंत्रों का एक छोटा सूक्त, जो पति और पत्नी के बीच एक संवाद है। लोपामुद्रा पहले बोलती है। वह कहती है कि बहुत-सी शरद ऋतुओं से उसने दिन-रात मेहनत की है, उन उषाओं के बीच जो हमें बूढ़ा करती हैं। बुढ़ापा शरीर की सुंदरता को घिस देता है। सत्य की सेवा करने वाले प्राचीन ऋषि भी आख़िर अपनी पत्नियों से मिले; पति अपनी पत्नियों के पास आएँ।",
 "c7306c28": "अगस्त्य जवाब देते हैं कि उनकी लंबी मेहनत बेकार नहीं गई, क्योंकि देवता प्रयत्न करने वालों की रक्षा करते हैं, और अब वे दोनों साथ मिलकर दोनों को पा सकते हैं। आख़िरी मंत्र कवि का विचार समेटता है: महान द्रष्टा अगस्त्य ने “दोनों का पोषण किया” — अपनी तपस्या का भी और अपने गृहस्थ जीवन का भी — और देवताओं के साथ सच्चा आशीर्वाद पाया। वेद में यह उन गिनी-चुनी जगहों में से है जहाँ एक स्त्री की आवाज़ अपनी इच्छा के बारे में, सीधे और गरिमा के साथ, बोलती है।",
 "8124e974": "लोपामुद्रा वेद की स्त्री द्रष्टाओं — ब्रह्मवादिनियों — में गिनी जाती है, और बाद की परंपरा उसे दिव्य माता की श्री विद्या उपासना की एक महान आचार्या के रूप में भी पूजती है।",
 "93d55328": "महाभारत, वन पर्व, तीर्थयात्रा पर्व (लोपामुद्रा की शर्त; राजा श्रुतर्वा, ब्रध्नाश्व और त्रसदस्यु; इल्वल के पास यात्रा)। ऋग्वेद 1.179, लोपामुद्रा और अगस्त्य का संवाद। श्री विद्या की लोपामुद्रा बाद की तांत्रिक परंपरा से हैं।",
 "2bf7bd56": "{lopamudra|लोपामुद्रा} ने अगस्त्य से कहा कि वे तपस्वी के चिथड़ों में नहीं, महल जैसे सुख-साधनों के साथ उसके पास आएँ।",
 "fd842ce4": "अगस्त्य ऐसा कोई धन नहीं लेते थे जिससे किसी को हानि हो; तीन ईमानदार राजाओं के पास देने को कुछ बचा नहीं था।",
 "2e4a291d": "ऋग्वेद 1.179 में लोपामुद्रा अपनी आवाज़ में बोलती है।",
 "695b19f9": "तीनों राजाओं के पास फ़ालतू पैसा नहीं था क्योंकि वे सब कुछ सही ढंग से अपनी प्रजा पर ख़र्च करते थे। जो राजा कुछ नहीं बचाता, वह अच्छा राजा है या लापरवाह?",
 "c7baf5d3": "“वातापि पच गया!”",
 "d1a8087f": "{ilvala|इल्वल} इतना ख़तरनाक क्यों था? महाभारत बताता है। एक बार इल्वल ने एक ब्राह्मण से वर माँगा था: “मुझे इंद्र जैसा बलवान पुत्र दो।” ब्राह्मण ने मना कर दिया। उस दिन से इल्वल सभी ब्राह्मणों से नफ़रत करने लगा, और अपने छोटे भाई {vatapi|वातापि} के साथ मिलकर उन्हें मारने की एक क्रूर योजना बनाई।",
 "9f169c78": "वातापि जब चाहे अपना रूप बदल सकता था। वह बकरा बन जाता, और इल्वल उसे पकाकर किसी ब्राह्मण अतिथि को बड़े आदर-भाव के दिखावे के साथ उसका मांस परोसता। फिर इल्वल पुकारता, “वातापि, बाहर आओ!” — और क्योंकि इल्वल में यमलोक भेजे गए किसी को भी वापस बुलाने की शक्ति थी, वातापि अतिथि के अंदर फिर से ज़िंदा हो जाता और हँसते हुए उसका शरीर फाड़कर बाहर निकल आता, और अतिथि मर जाता। इस तरह दोनों भाइयों ने बहुतों को मारा।",
 "debd3076": "मणिमती का भोज",
 "2cd35e53": "जब अगस्त्य और तीनों राजा पहुँचे, तो इल्वल ने बड़ी विनम्रता से उनका स्वागत किया और अपना हमेशा वाला भोजन तैयार किया। राजाओं ने बकरे को पकते देखा तो उनका दिल बैठ गया — वे यह चाल जानते थे। अगस्त्य ने कहा: “चिंता मत करो। इस महान असुर को मैं खुद खाऊँगा।”",
 "ec5be5db": "वे भोजन के सबसे आगे बैठे और सारा खा गए, एक-एक कौर, कि किसी और के लिए कुछ नहीं बचा। तब इल्वल ने मुस्कुराते हुए हमेशा की तरह पुकारा: “वातापि, बाहर आओ!” पर ऋषि के अंदर से सिर्फ़ हवा की एक बड़ी गड़गड़ाहट निकली। अगस्त्य ने धीरे से कहा: “वह बाहर कैसे आएगा? मैंने तो उसे पचा लिया।”",
 "7fb598da": "“वातापि पच गया।” तेलुगु परिवार आज भी बड़े भोजन के बाद बच्चे का पेट थपथपाते हुए यह कहते हैं — या “जीर्णम्, जीर्णम्, वातापि जीर्णम्।”",
 "1e9eb7bf": "इल्वल देता है",
 "7dc4fd9b": "महाभारत में इल्वल डर गया। उसका भाई हमेशा के लिए चला गया था, और उसके सामने एक ऐसे ऋषि बैठे थे जो उसके साथ भी यही कर सकते थे। हाथ जोड़कर उसने पूछा कि वे किसलिए आए हैं। अगस्त्य ने कहा: “हम जानते हैं कि तुम सबसे धनी हो। इन राजाओं के पास देने को धन नहीं बचा है। दूसरों को हानि पहुँचाए बिना इन्हें दो, और मुझे जो दे सको दो।”",
 "047c7747": "इल्वल ने हर राजा को दस हज़ार गायें और उतना ही सोना दिया। अगस्त्य को उसने उसका दुगुना दिया, और विराव और सुराव नाम के दो तेज़ घोड़ों वाला एक सोने का रथ। घोड़े पल भर में सारा धन अगस्त्य के आश्रम तक ले गए। और इस तरह लोपामुद्रा की इच्छा पूरी हुई — ऐसे धन से जो ईमानदार लोगों से नहीं, बल्कि एक हत्यारे से लिया गया था।",
 "c636ed63": "रामायण का रूप",
 "904a925b": "वहाँ इल्वल का अंत अलग है",
 "4e8bdf91": "वाल्मीकि रामायण में राम अगस्त्य के आश्रम की ओर जाते हुए लक्ष्मण को यह कथा सुनाते हैं। वहाँ इल्वल ब्राह्मण का वेश धरकर, शुद्ध संस्कृत बोलते हुए, ब्राह्मणों को श्राद्ध-भोज पर बुलाता है; वातापि मेढ़ा बन जाता है। हज़ारों मारे जाते हैं। जब अगस्त्य भोजन करके कहते हैं कि राक्षस पच गया, तो इल्वल ग़ुस्से में उन पर झपटता है — और अगस्त्य एक ही जलती नज़र से उसे भस्म कर देते हैं। महाभारत में इल्वल जीवित रहता है और अपना धन देता है; रामायण में वह मर जाता है।",
 "9e17eb75": "राम रास्ते में कथा सुनाते हैं",
 "ef21975e": "हज़ार के बराबर एक पुत्र",
 "6412b4fd": "अब अगस्त्य वह सब लेकर लोपामुद्रा के पास आए जो उसने माँगा था। उससे प्रसन्न होकर उन्होंने उसे चुनने को कहा: “क्या मैं तुम्हें हज़ार पुत्र दूँ, या सौ पुत्र जिनमें हर एक दस के बराबर हो, या दस पुत्र जिनमें हर एक सौ के बराबर हो — या एक पुत्र जो हज़ार के बराबर हो?” लोपामुद्रा ने कहा: “मुझे एक पुत्र दीजिए जो हज़ार के बराबर हो। बहुत-से बुरे पुत्रों से एक अच्छा और विद्वान पुत्र बेहतर है।”",
 "8cd67b38": "बच्चा सात साल तक उसके गर्भ में रहा। जब वह पैदा हुआ, तो अंगों सहित वेद और उपनिषद पढ़ता हुआ बाहर आया। उसका नाम {dridhasyu|दृढस्यु} रखा गया। छोटा-सा बालक होते हुए भी वह अपने पिता की पवित्र अग्नि के लिए लकड़ियों के भारी गट्ठर ढोता था, इसलिए उसे इध्मवाह, यानी “लकड़ी ढोने वाला”, भी कहा गया। और जो पितर गड्ढे में लटके थे, वे मुक्त हो गए और उन लोकों में पहुँच गए जिनकी उन्हें चाह थी।",
 "81b1d42c": "महाभारत, वन पर्व, तीर्थयात्रा पर्व — इल्वल और वातापि, दान और विराव-सुराव घोड़े, और दृढस्यु (इध्मवाह) का जन्म। वाल्मीकि रामायण, अरण्य कांड — अगस्त्य के आश्रम के रास्ते में राम की सुनाई कथा, जहाँ इल्वल अगस्त्य की नज़र से भस्म होता है। घरों में कही जाने वाली कहावत “वातापि जीर्णम्” जीवित लोक-परंपरा है।",
 "dbef9c53": "{ilvala|इल्वल} और {vatapi|वातापि} पके हुए बकरे से अतिथियों को मारते थे, जो फिर ज़िंदा हो जाता था।",
 "8229eb78": "अगस्त्य ने बकरा खा लिया और वातापि को हमेशा के लिए पचा लिया — “वातापि जीर्णम्।”",
 "c0566938": "लोपामुद्रा ने हज़ार के बराबर एक पुत्र चुना: {dridhasyu|दृढस्यु}, लकड़ी ढोने वाला।",
 "fcd9ce68": "लोपामुद्रा ने हज़ार साधारण पुत्रों की जगह एक महान पुत्र चुना। एक सच्चा दोस्त होना बेहतर है, या बहुत-से दोस्त? क्यों?",
 "b10a6b4e": "जो पर्वत झुक गया",
 "8c86abc6": "हर दिन सूर्य उगते और डूबते हैं, और पुराने ग्रंथ कहते हैं कि चलते हुए वे मेरु पर्वत की परिक्रमा करते हैं — संसार के बीच में खड़ा सोने का पर्वत। भारत के बीच फैली महान {vindhya|विंध्य} पर्वतमाला यह रोज़ देखती — और उसे जलन होने लगी।",
 "41e443fa": "महाभारत में विंध्य ने {surya|सूर्य} से कहा: “आप रोज़ मेरु की परिक्रमा करते हैं। मेरी भी उसी तरह परिक्रमा कीजिए।” सूर्य ने जवाब दिया: “मैं अपनी इच्छा से मेरु की परिक्रमा नहीं करता। यह मार्ग मेरे लिए उसने तय किया है जिसने संसार बनाया।” विंध्य आग-बबूला हो गया। वह बढ़ने लगा — ऊपर और ऊपर, यहाँ तक कि उसकी चोटियों ने आकाश में सूर्य और चंद्रमा का रास्ता रोक दिया।",
 "241a2bda": "दिन और रात का क्रम टूट गया, और सभी प्राणी कष्ट में पड़ गए। देवता आए और पर्वत से विनती की, पर वह नहीं रुका। तो वे उस एक ऋषि के पास गए जिनके बारे में वे जानते थे कि वे पर्वत से निपट सकते हैं: अगस्त्य।",
 "32a291f4": "“मेरे लौटने तक रुको”",
 "31c3672a": "अगस्त्य {lopamudra|लोपामुद्रा} के साथ निकले और विंध्य की तलहटी में पहुँचे। अगस्त्य ने पर्वत से कहा: “पर्वतों में श्रेष्ठ, मुझे दक्षिण में काम है और तुम्हें पार करना है। मुझे रास्ता दो। और जब तक मैं लौट न आऊँ, ऐसे ही रहना। उसके बाद जितना चाहो बढ़ना।”",
 "f651f94e": "ऋषि के प्रति आदर से विंध्य नीचे झुक गया और मान गया। अगस्त्य पार करके दक्षिण चले गए — और कभी नहीं लौटे। आज तक विंध्य अपना वचन निभाता है और नीचा रहता है, उस ऋषि की राह देखता हुआ जो आने वाले नहीं। सूर्य और चंद्रमा फिर से अपने रास्ते चलते हैं, और संसार को उसके दिन और रातें मिल गईं।",
 "9e663835": "अगस्त्य के नाम को यही अर्थ दिया जाता है: जिसने पर्वत (*अग*) को रोका (*स्तंभ्*)। इसीलिए वे दक्षिण के ऋषि भी बने — उन्होंने विंध्य पार किया और वहीं रह गए।",
 "cbb548dd": "काशी से विदा — स्कंद पुराण",
 "12454a1a": "स्कंद पुराण का काशी खंड यही कथा और भी भाव के साथ सुनाता है। वहाँ {narada|नारद} विंध्य के पास जाते हैं और उसके सामने मेरु पर्वत की प्रशंसा करते हैं, जिससे उसका घमंड भड़क उठता है। और जब देवता आते हैं, तब अगस्त्य काशी में रह रहे हैं — वाराणसी, शिव की अपनी नगरी, जिससे वे सबसे ज़्यादा प्रेम करते हैं।",
 "a25f9042": "संसार की भलाई के लिए वे जाने को मान जाते हैं, पर उनका दिल टूट जाता है। वे रोते हुए काशी से निकलते हैं, बार-बार मुड़कर नगरी को देखते हुए, और लोपामुद्रा उनके साथ होती है। क्योंकि वे कभी लौटने वाले नहीं थे, पुराण उनकी दक्षिण-यात्रा को एक बलिदान बताता है: ऋषि ने अपनी सबसे प्यारी जगह छोड़ दी ताकि सूर्य सब पर चमक सकें। वही पुराण कहता है कि रास्ते में वे कोल्हापुर में देवी महालक्ष्मी के दर्शन करने गए।",
 "7fdd1291": "महाभारत में यह कथा समुद्र पीने की कथा के अंदर सुनाई गई है: देवता अगस्त्य की स्तुति करते हुए उन्हें याद दिलाते हैं कि उन्होंने एक बार विंध्य को रोका था, और युधिष्ठिर लोमश से इसे समझाने को कहते हैं।",
 "7bf8c7e8": "महाभारत, वन पर्व, तीर्थयात्रा पर्व — विंध्य के बारे में लोमश का वृत्तांत। स्कंद पुराण, काशी खंड — नारद और विंध्य, काशी छोड़ते समय अगस्त्य का दुख, और उनकी कोल्हापुर यात्रा।",
 "44abb154": "मेरु से जलकर {vindhya|विंध्य} इतना बढ़ा कि उसने सूर्य का रास्ता रोक दिया।",
 "c01f8bbc": "अगस्त्य ने उससे कहा कि उनके लौटने तक नीचा रहे — और वे कभी नहीं लौटे।",
 "6b447bd1": "काशी खंड में वे संसार की भलाई के लिए रोते हुए अपनी प्यारी काशी छोड़ते हैं।",
 "9f9670ed": "अगस्त्य पर्वत से लड़े नहीं — उन्होंने बस उससे रुकने को कहा। तुमने कब देखा है कि कोई नरम चतुराई ज़ोर-ज़बरदस्ती से बेहतर काम कर गई?",
 "76b5d27b": "समुद्र को पी जाना",
 "17c41834": "देवताओं के युग में एक भयानक असुर {vritra|वृत्र} रहता था, और उसके साथ {kalakeyas|कालकेय} नाम के क्रूर दानवों का एक कुल। आख़िरकार {indra|इंद्र} ने वज्र से वृत्र को मार डाला — वह वज्र जो ऋषि दधीचि की हड्डियों से बना था। पर कालकेय बच निकले। इंद्र से डरकर वे समुद्र में कूद पड़े — शार्कों, व्हेलों और रत्नों के घर में — और उसकी उन गहराइयों में छिप गए जहाँ कोई देवता नहीं पहुँच सकता था।",
 "0eeef40a": "वहाँ से उन्होंने तीनों लोकों को जड़ से नष्ट करने की योजना बनाई। “लोक तपस्या और यज्ञ पर टिके हैं,” उन्होंने कहा। “तपस्वियों को मार डालो, तो सब कुछ गिर जाएगा।” तो हर रात वे समुद्र से निकलते और आश्रमों पर हमला करते — वसिष्ठ के, च्यवन के, भरद्वाज के और कई दूसरों के — और ऋषियों को सोते या प्रार्थना करते हुए मार डालते। दिन में वे फिर लहरों के नीचे ग़ायब हो जाते। लोगों को सुबह सिर्फ़ हड्डियाँ मिलतीं, और कोई नहीं जानता था कि हत्यारे कौन हैं।",
 "aa020047": "वज्र के लिए दधीचि के अपनी हड्डियाँ दान करने की कथा अपने आप में एक बड़ी कथा है — महान ऋषियों में उनकी अपनी जगह होगी।",
 "e22ab017": "“यह सिर्फ़ अगस्त्य कर सकते हैं”",
 "1a1b5e69": "यज्ञ रुक गए। वेद चुप हो गए। संसार डर गया। देवता नारायण, {vishnu|विष्णु}, के पास गए, और उन्होंने रहस्य बताया: “हत्यारे कालकेय हैं, जो समुद्र में छिपे हैं। जब तक समुद्र उनकी रक्षा करता है, तुम उन्हें नष्ट नहीं कर सकते। तुम्हें समुद्र को सुखाना होगा — और यह सिर्फ़ अगस्त्य कर सकते हैं।”",
 "232a1653": "देवता अगस्त्य के आश्रम गए और उनके सारे कामों का बखान करते हुए उनकी स्तुति की: “आपने एक बार हमें नहुष से बचाया था, जो स्वर्ग का राजा बन गया था और आपके वचन से गिरा। जब विंध्य ने सूर्य का रास्ता रोका, तो आपने उसे रोका। अब फिर से लोकों को बचाइए।” अगस्त्य ने सुना। “तुम जो कहते हो, मैं करूँगा,” उन्होंने कहा, “लोकों की भलाई के लिए।”",
 "0cee0a34": "एक घूँट",
 "3f3bfdd3": "तो देवता, ऋषि, गंधर्व और अनगिनत प्राणी अगस्त्य के पीछे-पीछे तट तक गए। समुद्र उनके सामने गरज रहा था, उसकी लहरें नर्तकों की तरह उछल रही थीं। अगस्त्य किनारे पर खड़े हुए और बोले: “लोकों की भलाई के लिए, अब मैं यह समुद्र पी जाऊँगा।” और पूरी सृष्टि की आँखों के सामने उन्होंने उसे पी लिया — पूरा विशाल सागर, जब तक उसका तल नंगा और सूखा न रह गया।",
 "fdeef50a": "कालकेय खुले में पड़े थे। देवता अपने अस्त्रों के साथ उन पर टूट पड़े, और जिन दानवों ने इतने ऋषियों की हत्या की थी, वे नष्ट हो गए। कुछ बचे हुए धरती फाड़कर नीचे पाताल लोक में भाग गए।",
 "6aede1d0": "कालकेय महाभारत में आगे फिर आते हैं: स्वर्ग में रहते समय अर्जुन ने पौलोमों और कालकेयों से उनकी उड़ने वाली नगरी हिरण्यपुर में युद्ध किया।",
 "c4f42b35": "“वह पानी पच गया”",
 "cf2c11f4": "तब देवताओं ने ख़ुशी से कहा: “महर्षि, अब जो पानी आपने पिया, उससे समुद्र को फिर भर दीजिए।” अगस्त्य ने जवाब दिया: “वह पानी तो मैंने पचा लिया। इसे भरने का कोई और उपाय सोचो।” देवता चकित हुए — और चिंतित भी। इतने प्राणियों का घर, समुद्र, ख़ाली पड़ा था।",
 "0aa6419f": "वे {brahma|ब्रह्मा} के पास गए, जिन्होंने कहा: “देवताओ, अपने घर लौट जाओ। बहुत समय बाद समुद्र फिर भरेगा — राजा {bhagiratha|भगीरथ} के महान प्रयत्न से, उनके पितरों के लिए।” और ऐसा ही हुआ: सगर के साठ हज़ार पुत्रों की, और स्वर्ग से गंगा के उतरने की कथा ही इसकी कथा है कि समुद्र फिर कैसे भरा। युधिष्ठिर लोमश से ठीक यही पूछते हैं, और लोमश आगे यही कथा सुनाते हैं।",
 "b79bfc85": "सगर के पुत्र और भगीरथ की गंगा",
 "88835d34": "महाभारत, वन पर्व, तीर्थयात्रा पर्व — लोमश कालकेयों, विष्णु की सलाह, देवताओं द्वारा अगस्त्य की स्तुति, समुद्र पीने और भगीरथ के बारे में ब्रह्मा के वचन की कथा सुनाते हैं; उसके बाद सगर की कथा आती है। अर्जुन और कालकेय: वन पर्व, निवातकवच-युद्ध पर्व।",
 "f1e23490": "{kalakeyas|कालकेय} समुद्र में छिपकर रात को ऋषियों को मारते थे।",
 "c71c4243": "अगस्त्य पूरा समुद्र पी गए, और देवताओं ने राक्षसों को नष्ट कर दिया।",
 "5821ff5c": "उन्होंने पानी पचा लिया था, इसलिए समुद्र फिर से सिर्फ़ भगीरथ की गंगा से ही भरा।",
 "4f5ddc8e": "अगस्त्य ने एक समस्या सुलझाई पर समुद्र ख़ाली छोड़ दिया, और उसे ठीक करने में भगीरथ के वंश को पीढ़ियाँ लगीं। क्या बड़े हल कभी-कभी नई समस्याएँ पैदा कर देते हैं? क्या तुम कोई उदाहरण सोच सकते हो?",
 "66e862d4": "नहुष का पतन",
 "1b913fe5": "एक बार {indra|इंद्र} को स्वर्ग छोड़ना पड़ा। वृत्र को मारने के बाद, और उससे पहले तीन सिर वाले विश्वरूप को, ब्रह्महत्या का पाप उनसे चिपक गया, और वे जाकर एक दूर की झील में कमल की डंडी के अंदर, बहुत छोटे और अदृश्य होकर छिप गए। स्वर्ग का कोई राजा नहीं रहा। देवताओं और ऋषियों ने किसी योग्य व्यक्ति को ढूँढा, और उन्होंने धरती का एक राजा चुना: चंद्रवंश के {nahusha|नहुष}, {yayati|ययाति} के पिता, जो अपने सद्गुणों के लिए प्रसिद्ध थे।",
 "c3233584": "राज करने में उनकी मदद के लिए उन्होंने उन्हें एक वर दिया: वे जिसकी ओर देखेंगे, उसकी शक्ति अपने अंदर ले लेंगे। इससे नहुष तीनों लोकों के राजा बन गए। पर सत्ता ने उन्हें बदल दिया। वे भोग-विलास में डूब गए, और फिर उनकी नज़र इंद्र की रानी {shachi|शची} पर पड़ी। “अब मैं इंद्र हूँ,” उन्होंने कहा। “इंद्र की पत्नी मेरे पास आए।”",
 "a8ed9a17": "शची की चतुर माँग",
 "cbcbfe35": "शची डर गईं और रक्षा के लिए देवताओं के गुरु {brihaspati|बृहस्पति} के पास गईं। बृहस्पति ने उन्हें शरण दी और सलाह दी: “नहुष से समय माँगो, और फिर उससे कुछ ऐसा माँगो जिससे वह अपने ही घमंड से गिर जाए।” इस बीच शची ने इंद्र को उनकी कमल की डंडी में ढूँढ लिया, और उन्होंने बताया कि क्या कहना है।",
 "e471df9f": "वे नहुष के पास आईं और बोलीं: “मैं एक शर्त पर तुम्हारी बनूँगी। मेरे पास ऐसे वाहन में आओ जिसका पहले कभी किसी ने उपयोग न किया हो — न घोड़े, न हाथी, न रथ। महान ऋषि खुद तुम्हारी पालकी उठाएँ।” नहुष ख़ुश हो गए। “यह वाहन मेरे योग्य है!” उन्होंने कहा, और ऋषियों को अपनी पालकी में जोत दिया।",
 "7b87205a": "कमल की डंडी के अंदर छिपे इंद्र महाभारत की वह तस्वीर हैं कि अपने ही ग़लत कामों के बोझ तले देवताओं का राजा भी कितना छोटा हो जाता है।",
 "a8dc909b": "ऋषि के सिर पर पैर",
 "8548ce06": "पालकी उठाने वाले ऋषियों में अगस्त्य भी थे। चलते-चलते नहुष ऋषियों से वेद पर बहस करने लगे, और उन मंत्रों का मज़ाक उड़ाने लगे जिन्हें ऋषि पवित्र मानते थे, और अपनी जल्दबाज़ी और घमंड में उन्होंने अगस्त्य के सिर को पैर से छू दिया। उद्योग पर्व कहता है कि तब अगस्त्य ने श्राप दिया: “तुमने वह किया है जो नहीं करना चाहिए, और मेरे सिर पर लात मारी है, इसलिए स्वर्ग से गिरो, नीच! धरती पर दस हज़ार साल तक एक बड़ा साँप बनकर रहो। उसके बाद तुम स्वर्ग लौटोगे।” उसी पल नहुष का तेज उन्हें छोड़ गया, और वे गिर पड़े।",
 "30e1db42": "इंद्र अपने सिंहासन पर लौट आए। और देवताओं को उसके बाद हमेशा याद रहा कि अगस्त्य ने उन्हें बचाया था — जैसा उन्होंने तब याद दिलाया जब वे उनसे समुद्र पीने को कहने आए।",
 "bc325a57": "एक और रूप: अगस्त्य की जटाओं में भृगु",
 "edfad41a": "अनुशासन पर्व से",
 "123305a8": "अनुशासन पर्व इसे अलग ढंग से बताता है। अपने वर से नहुष इतने शक्तिशाली हो गए थे कि जब तक उनकी नज़र अगस्त्य पर थी, अगस्त्य भी उन्हें श्राप नहीं दे सकते थे। तो ऋषि {bhrigu|भृगु} अगस्त्य की जटाओं में छिप गए, किसी को दिखाई न देते हुए। जब नहुष ने अगस्त्य को लात मारी, तो भृगु ने ही श्राप देकर राजा को साँप बना दिया।",
 "c3be236d": "बाद की कथाएँ एक शब्द-खेल जोड़ती हैं: ऋषियों को जल्दी चलने को कहते हुए नहुष चिल्लाए “सर्प, सर्प!” — यानी “चलो, चलो!” — और श्राप ने जवाब दिया, “तो सर्प बन जाओ” — यानी साँप।",
 "ef3017df": "वन का अजगर",
 "aab2adfa": "युगों बाद, जब पांडव वन में थे, {bhima|भीम} को एक विशाल अजगर ने जकड़ लिया और अपनी सारी ताक़त के बावजूद वे छूट नहीं सके। {yudhishthira|युधिष्ठिर} उन्हें ढूँढते हुए आए। अजगर ने कहा: “मैं नहुष हूँ, तुम्हारा पूर्वज। अगस्त्य ने मुझे श्राप दिया था। गिरते हुए मैंने उनसे श्राप के अंत की विनती की, और उन्होंने कहा कि जो मेरे प्रश्नों के उत्तर दे सकेगा, वह मुझे मुक्त करेगा। अगर तुम मेरे प्रश्नों के उत्तर दो, तो मैं तुम्हारे भाई को छोड़ दूँगा।” उसने पूछा कि सच्चा ब्राह्मण कौन होता है, और जानने योग्य सबसे ऊँची चीज़ क्या है। युधिष्ठिर ने उत्तर दिया कि ब्राह्मण की पहचान सत्य, दान, धैर्य, अच्छे आचरण, दया और आत्म-संयम से होती है — सिर्फ़ जन्म से नहीं।",
 "346a8dbc": "संतुष्ट होकर नहुष ने भीम को छोड़ दिया। श्राप ख़त्म हुआ; उन्होंने अपना तेजस्वी रूप पाया और स्वर्ग चले गए। अगस्त्य का श्राप, कितना भी भयानक रहा हो, अपने अंत के साथ आया था — और वह अंत धर्म की सच्ची बात सुनने से आया।",
 "efa8d757": "महाभारत, उद्योग पर्व, इंद्रविजय (युधिष्ठिर को शल्य की सुनाई कथा: कमल में इंद्र, नहुष, शची, ऋषियों की पालकी, अगस्त्य का श्राप)। अनुशासन पर्व (अगस्त्य की जटाओं में छिपे भृगु वाला रूप)। वन पर्व, आजगर पर्व (अजगर नहुष, भीम और युधिष्ठिर)। “सर्प, सर्प” का शब्द-खेल बाद की कथाओं का है।",
 "3e0f6f7f": "{nahusha|नहुष} स्वर्ग के राजा बने, घमंडी हो गए, और इंद्र की रानी {shachi|शची} को चाहने लगे।",
 "9170293e": "धर्म के बारे में युधिष्ठिर के उत्तरों ने नहुष को श्राप से मुक्त किया।",
 "a0291eaa": "श्राप, बारिश और कमल की डंडियाँ",
 "76160acd": "अगस्त्य सच्चे लोगों पर दयालु थे, पर घमंड पर उनका क्रोध तेज़ और प्रचंड होता था। कई पुरानी कथाएँ उनके श्रापों के बारे में बताती हैं — और बार-बार वह श्राप किसी अच्छी बात की शुरुआत बन जाता है।",
 "0727dd5f": "वह राजा जो उठा नहीं — गजेंद्र",
 "183f11db": "भागवत पुराण {indradyumna|इंद्रद्युम्न} के बारे में बताता है, जो तमिल देश के एक पांड्य राजा और विष्णु के बड़े भक्त थे। उन्होंने अपना राज्य छोड़ दिया था और मलय पर्वत पर मौन रहकर पूजा कर रहे थे। अगस्त्य अपने शिष्यों के साथ आए — और राजा, अपने मौन व्रत में डूबे हुए, न उठे और न उनका स्वागत किया। अगस्त्य को सिर्फ़ घमंड और उपेक्षा दिखी। “यह राजा एक सुस्त हाथी की तरह बैठा है, अतिथि की अनदेखी करते हुए,” उन्होंने कहा। “यह हाथी बनकर जन्म ले।”",
 "559774e4": "तो इंद्रद्युम्न त्रिकूट पर्वत पर हाथियों के राजा गजेंद्र बनकर पैदा हुए। एक दिन एक झील में एक मगरमच्छ ने उनका पैर पकड़ लिया, और लंबे, निराश संघर्ष के बाद हाथी ने अपनी सूँड़ में एक कमल उठाकर भगवान को पुकारा। विष्णु गरुड़ पर आए, अपने चक्र से मगरमच्छ को काटा, और उन्हें छुड़ाया। श्राप के कारण ही हाथी में राजा की पुरानी भक्ति जाग उठी — और वे विष्णु तक पहुँच गए।",
 "8c88dcf2": "पोतना का तेलुगु भागवतम् गजेंद्र की कथा इतनी सुंदरता से सुनाता है कि तेलुगु बच्चे आज भी उसके पद्य सीखते हैं — हाथी की पुकार “एव्वनिचे जनिंचु” से उस भाषा की सबसे प्रसिद्ध कविताओं में से एक शुरू होती है।",
 "69ba8268": "थूकने वाला यक्ष",
 "552a87fc": "महाभारत में धन के स्वामी {kubera|कुबेर} एक बार अपने यक्षों के साथ आकाश में उड़ते हुए कुशवती जा रहे थे। उनके नीचे यमुना के किनारे अगस्त्य तपस्या में बैठे थे। कुबेर के मित्र, यक्ष {manimat|मणिमान}, ने मूर्खता और घमंड में ऊपर से महान ऋषि के सिर पर थूक दिया।",
 "6ae9e783": "अगस्त्य भड़क उठे। उन्होंने कुबेर से कहा: “तुम्हारी आँखों के सामने तुम्हारे मित्र ने मेरा अपमान किया है, इसलिए वह और तुम्हारी सेना एक मनुष्य के हाथों मारे जाएँगे। तुम उनके लिए शोक करोगे — पर जब तुम उस मनुष्य को देखोगे, तो इस दुख से मुक्त हो जाओगे।” बहुत समय बाद {bhima|भीम} द्रौपदी के लिए सोने के कमल लाने कुबेर के पर्वत पर आए, यक्षों से लड़े और मणिमान को मार डाला। तब कुबेर ने यह कथा सुनाई और कहा कि भीम ने उन्हें अगस्त्य के श्राप से मुक्त किया है।",
 "9f0f55d4": "ताड़का और मारीच",
 "672ae4b7": "रामायण एक कठोर कथा सुनाती है। यक्षिणी {tataka|ताड़का} का विवाह {sunda|सुंद} से हुआ था, और अगस्त्य के श्राप से सुंद मारा गया। तब ताड़का और उसका पुत्र {marica|मारीच} गरजते हुए ऋषि को खा जाने के लिए उन पर झपटे। अगस्त्य ने दोनों को श्राप दिया: मारीच को राक्षस बनने का, और ताड़का को अपनी सुंदरता खोकर एक भयानक नरभक्षी बनने का। ग़ुस्से में उसने वह पूरा इलाक़ा उजाड़ दिया जहाँ अगस्त्य रहे थे — जब तक विश्वामित्र नन्हे राम को वहाँ नहीं ले आए।",
 "95f91023": "राम ताड़का से मिलते हैं",
 "193dd2bf": "इस तरह अगस्त्य के श्राप ने मारीच को राक्षस बनाया — और मारीच एक दिन वह सोने का हिरण बना जो राम को सीता से दूर ले गया।",
 "f457ed3f": "जब इंद्र ने बारिश नहीं भेजी",
 "1f166a31": "कमल की डंडियाँ किसने चुराईं?",
 "37cf8b9f": "अनुशासन पर्व में एक कोमल कथा है। एक बार महान ऋषियों का एक दल साथ-साथ तीर्थयात्रा पर गया, और एक पवित्र झील पर अगस्त्य ने अपने भोजन के लिए कमल की डंडियाँ इकट्ठी कीं। वे ग़ायब हो गईं। अगस्त्य ने अपने साथियों से पूछा कि उन्हें किसने लिया — और हर ऋषि ने अपनी बेगुनाही साबित करने के लिए एक गंभीर शपथ ली: “जिसने उन्हें चुराया, उस पर यह या वह विपत्ति आए!” हर शपथ में एक ऐसी कमी का नाम था जिसमें किसी अच्छे इंसान को कभी नहीं पड़ना चाहिए।",
 "c5be3d38": "अंत में इंद्र प्रकट हुए और मुस्कुराते हुए मान गए: “उन्हें मैंने लिया था। मैंने ऐसा सिर्फ़ तुमसे ये शपथें सुनने के लिए किया, क्योंकि इनमें पूरा धर्म है।” उन्होंने कमल की डंडियाँ लौटा दीं, और ऋषि अपने रास्ते चल पड़े।",
 "3a1cc603": "भागवत पुराण 8.4 (अगस्त्य द्वारा इंद्रद्युम्न को श्राप; गजेंद्र की मुक्ति 8.2–8.4 में)। महाभारत, वन पर्व, यक्ष-युद्ध (मणिमान और कुबेर); आश्वमेधिक पर्व (अगस्त्य का बारह साल का यज्ञ); अनुशासन पर्व (कमल की डंडियों की चोरी)। वाल्मीकि रामायण, बाल कांड (ताड़का, सुंद और मारीच, विश्वामित्र के मुँह से)। पोतना का आंध्र महाभागवतम्, स्कंध 8।",
 "cd4ec1fc": "अगस्त्य ने {indradyumna|इंद्रद्युम्न} को हाथी बनने का श्राप दिया; गजेंद्र के रूप में विष्णु ने उन्हें बचाया।",
 "84f3c1e1": "उनके श्राप {manimat|मणिमान}, ताड़का और मारीच पर पड़े — और हर एक आगे एक बड़ी कथा तक ले गया।",
 "063a1f0d": "उन्होंने इंद्र से बारिश करवाई, और इंद्र ने ऋषियों से धर्म की बात सुनने के लिए उनकी कमल की डंडियाँ चुराईं।",
 "0d9c1cf6": "इंद्रद्युम्न घमंडी नहीं थे — वे मौन व्रत रख रहे थे — फिर भी अगस्त्य ने उन्हें श्राप दिया। क्या वह श्राप उचित था? और तुम्हें क्या लगता है, फिर भी वह उन्हें भगवान तक क्यों ले गया?",
 "db24f32b": "अगस्त्य और राम",
 "20263af3": "वन के आश्रमों के बीच दस साल रहने के बाद {rama|राम} {sita|सीता} और {lakshmana|लक्ष्मण} के साथ {sutikshna|सुतीक्ष्ण} के आश्रम लौटे। “मैं महान अगस्त्य के दर्शन करना चाहता हूँ,” राम ने कहा। सुतीक्ष्ण ने उन्हें रास्ता बताया: पहले अगस्त्य के भाई के आश्रम, फिर आगे खुद अगस्त्य के पास। वन में चलते हुए राम ने लक्ष्मण को इल्वल और वातापि की कथा सुनाई, और उनका मन उस ऋषि से मिलने की उत्सुकता से भरा था जिन्होंने दक्षिण को सुरक्षित बनाया था।",
 "1271b789": "राम वहाँ कहते हैं कि जब से अगस्त्य आए हैं, राक्षस दक्षिण में रहने की हिम्मत नहीं करते; वे बस दूर से उसे देखते हैं। अगस्त्य का आश्रम इतना पवित्र था कि कोई झूठा, कोई क्रूर आदमी, कोई दुष्ट वहाँ नहीं रह सकता था। लक्ष्मण उनके आने की ख़बर देने आगे गए, और महान ऋषि खुद उनका स्वागत करने बाहर आए।",
 "b18170a5": "उपहार",
 "df5c12aa": "अगस्त्य ने राम का एक सम्मानित अतिथि की तरह स्वागत किया और उन्हें बड़े-बड़े उपहार दिए: विश्वकर्मा का बनाया महान धनुष, जो विष्णु का था; ब्रह्मा का दिया एक चमचमाता बाण; इंद्र के दो तरकश जो कभी ख़ाली नहीं होते; और सोने की म्यान में एक तलवार। इनसे, उन्होंने राम से कहा, वे वैसे ही जीतेंगे जैसे इंद्र वज्र से जीतते हैं।",
 "60df0211": "उन्होंने कठिनाइयों में पति के पीछे चलने के लिए सीता की प्रशंसा की, और राम से उनका ध्यान रखने को कहा। फिर उन्होंने उन्हें गोदावरी के किनारे पंचवटी भेजा, फलों और पानी वाली एक सुंदर जगह, ताकि वे वहाँ रहकर ऋषियों की रक्षा करें। वहीं शूर्पणखा आने वाली थी, और युद्ध की महान कथा शुरू होने वाली थी।",
 "233d132f": "अगस्त्य के उपहार — पूरा अध्याय",
 "620536ee": "जब सुग्रीव सीता को ढूँढने के लिए वानरों को दक्षिण भेजते हैं, तो वे मलय पर्वत को, जहाँ अगस्त्य रहते हैं, दक्षिण के बड़े पहचान-चिह्नों में से एक बताते हैं।",
 "1bc66b55": "उत्तर कांड के कथावाचक",
 "11f63e35": "उन्होंने ऋषि पुलस्त्य और उनके पुत्र विश्रवा की कथा सुनाई; {ravana|रावण}, कुंभकर्ण और विभीषण के जन्म की; रावण की भयानक तपस्या और वरदानों की, उसकी विजयों की, स्त्रियों और देवताओं के उसके अपमान की। उन्होंने वाली और सुग्रीव की कथा सुनाई, और {hanuman|हनुमान} के बचपन की — कैसे बच्चे के रूप में वे उगते सूर्य को फल समझकर उस पर झपटे। जिस ऋषि ने राम को युद्ध के लिए अस्त्र दिए थे, अब उन्होंने उन्हें उसका अर्थ समझाया।",
 "7d4d7f4a": "अगस्त्य राम को राजा दंड और दंडक वन की कथा सुनाते हैं",
 "4daa7628": "शंबूक, और राजा श्वेत की भूख",
 "14b53a9f": "उत्तर कांड राम को एक आख़िरी बार अगस्त्य के पास लाता है, पूरी रामायण की सबसे कठिन घटनाओं में से एक के बाद। एक ब्राह्मण का छोटा बेटा मर गया था, और पिता ने राजा को दोष दिया। राम को बताया गया कि इसका कारण {shambuka|शंबूक} नाम का एक शूद्र तपस्वी है, जो उस तरह तपस्या कर रहा था जिसे उस समय की व्यवस्था मना करती थी। राम ने उसे ढूँढा और तलवार से उसे मार डाला, और बालक फिर से जी उठा। ग्रंथ यह बात सीधे-सीधे बताता है; पुराने और नए समय के बहुत-से पाठकों को यह बहुत खटकने वाली लगी है, और इस पर गहराई से सोचना ठीक है।",
 "404cc169": "वहाँ से राम पुष्पक विमान में उड़कर अगस्त्य के आश्रम गए। ऋषि ने उनका स्वागत किया और उन्हें विश्वकर्मा का बनाया, सूर्य की तरह चमकता एक दिव्य आभूषण दिया। राम किसी ऋषि से उपहार लेने में झिझके, पर अगस्त्य ने उन्हें उसकी कथा सुनाई। बहुत पहले विदर्भ के {shveta|श्वेत} नाम के एक राजा ने बड़ी तपस्या की थी और स्वर्ग गए थे — पर अपने पूरे जीवन में उन्होंने कभी किसी को अन्न नहीं दिया था। इसलिए स्वर्ग में वे हमेशा भूखे रहते, और उन्हें धरती पर उतरकर अपने ही मृत शरीर को खाना पड़ता, जो एक झील के किनारे पड़ा था। ब्रह्मा ने उनसे कहा कि जब अगस्त्य वहाँ आएँगे तब वे मुक्त होंगे। अगस्त्य आए; श्वेत ने उन्हें वह आभूषण दिया, और उस दान से वे हमेशा के लिए अपनी भूख से मुक्त हो गए।",
 "3df2a232": "वाल्मीकि रामायण, अरण्य कांड (सुतीक्ष्ण का बताया रास्ता, अगस्त्य के भाई का आश्रम, राम का अगस्त्य-वर्णन, उपहार और पंचवटी); किष्किंधा कांड (सुग्रीव का दक्षिण-वर्णन); उत्तर कांड (अगस्त्य का राक्षसों के इतिहास, वाली, सुग्रीव और हनुमान का वर्णन; शंबूक; श्वेत का आभूषण; दंड)।",
 "b9bd2943": "अगस्त्य ने राम को विष्णु का धनुष, ब्रह्मा का बाण, इंद्र के तरकश और एक तलवार दी।",
 "2468135f": "उन्होंने राम को पंचवटी भेजा, और युद्ध के बाद उन्हें रावण और हनुमान का इतिहास सुनाया।",
 "48515c75": "{shveta|श्वेत}, जिन्होंने कभी अन्न-दान नहीं किया था, अगस्त्य को दान देकर भूख से मुक्त हुए।",
 "32dfdc1c": "राजा श्वेत ने बड़ी तपस्या की पर कभी किसी को खाना नहीं खिलाया, और स्वर्ग में भी भूखे रहे। तुम्हें क्या लगता है, यह कथा प्रार्थना और दया के बारे में क्या सिखा रही है?",
 "3d8bdb9f": "लंका में युद्ध कई दिनों से चल रहा था। कुंभकर्ण गिर चुका था, और इंद्रजीत, और राक्षसों के बड़े-बड़े सेनापति। आख़िरकार {ravana|रावण} खुद राम से लड़ने निकला, और उनके बीच का युद्ध पहले के किसी भी युद्ध से भयानक था। द्वंद्व चलता रहा, चलता रहा, और लंबी लड़ाई से थके राम सोचते हुए खड़े थे, और रावण फिर से लड़ने को तैयार उनके सामने था।",
 "fc7b90a8": "देवता देखने के लिए आकाश में इकट्ठे हुए थे। उनमें अगस्त्य भी थे। राम की थकान देखकर ऋषि युद्ध के मैदान में उतरे और उनके पास खड़े हो गए।",
 "f33a49a8": "तब युद्ध से थककर चिंता में डूबे खड़े राम को, और सामने युद्ध के लिए तैयार रावण को देखकर, देवताओं के साथ युद्ध देखने आए पवित्र ऋषि अगस्त्य राम के पास आए और बोले।",
 "b5513e1e": "“यह प्राचीन रहस्य सुनो”",
 "29c04033": "“राम, राम, महाबाहु, यह प्राचीन रहस्य सुनो, जिससे, वत्स, तुम युद्ध में अपने सारे शत्रुओं को जीत लोगे।”",
 "8c1cb9cb": "तब अगस्त्य ने उन्हें आदित्य हृदयम्, यानी “सूर्य का हृदय”, सिखाया — {surya|सूर्य} का एक स्तोत्र, जो प्रकाश और जीवन के दाता हैं। यह पवित्र है, सारे शत्रुओं का नाश करता है, विजय दिलाता है, और दुख और चिंता दूर करता है, ऋषि ने कहा। यह आयु बढ़ाता है और सारे आशीर्वादों में सबसे श्रेष्ठ है।",
 "58fd96b9": "यह स्तोत्र सूर्य को एक साथ सारे देवताओं के रूप में देखता है। वे ब्रह्मा, विष्णु और शिव हैं; वे स्कंद और प्रजापति हैं; वे इंद्र, कुबेर, काल और मृत्यु, चंद्रमा और वरुण हैं; वे पितर, वसु, मरुत, प्राण, ऋतुओं के बनाने वाले हैं। वे उगते हैं तो संसार जागता है; वे डूबते हैं तो वह सो जाता है। जब सब प्राणी सोते हैं, तब भी वे उनमें जागते रहते हैं। सूर्य की स्तुति करना सभी देवताओं के पीछे के एक प्रकाश की स्तुति करना है।",
 "b947c462": "विजय",
 "0d2f2c63": "“जो इसे संकट में, कठिनाई में, वन में या भय में पढ़ता है, वह नष्ट नहीं होता,” अगस्त्य ने कहा। “स्थिर मन से देवताओं के स्वामी की पूजा करो। इसे तीन बार पढ़ो, और तुम यह युद्ध जीत जाओगे। इसी क्षण, महाबाहु, तुम रावण का वध करोगे।” और यह कहकर ऋषि जिस रास्ते आए थे उसी से लौट गए।",
 "ef262050": "राम का दुख दूर हो गया। शुद्ध होकर उन्होंने तीन बार आचमन किया, सूर्य की ओर देखा और तीन बार स्तोत्र का पाठ किया, और उनका मन आनंद से भर गया। उन्होंने अपना धनुष उठाया और दृढ़ निश्चय के साथ रावण की ओर मुड़े। और देवताओं के बीच खड़े सूर्य ने ख़ुशी से राम को देखा और कहा: “जल्दी करो!” — यह जानते हुए कि रावण का अंत पास है। उसके बाद के भयंकर युद्ध में राम ने बार-बार रावण के सिर काटे, और आख़िर में ब्रह्मास्त्र से उसे मार डाला।",
 "93c115f7": "करोड़ों लोग आज भी हर सुबह उगते सूर्य की ओर मुँह करके आदित्य हृदयम् का पाठ करते हैं। कई तेलुगु घरों में इसे रविवार को और सूर्य के त्योहार रथ सप्तमी पर गाया जाता है।",
 "2347f67a": "वाल्मीकि रामायण, युद्ध कांड — आदित्य हृदयम्, जो रावण के साथ आख़िरी द्वंद्व से ठीक पहले गाया गया। यह दक्षिणी पांडुलिपियों और लोकप्रिय संस्करणों में मिलता है; बड़ौदा का समीक्षित संस्करण इसे उन अंशों में रखता है जिन्हें वह बाद में जोड़ा गया मानता है। जो भी हो, कई सदियों से इसे अगस्त्य की सीख के रूप में संजोया गया है।",
 "2807a28f": "आख़िरी द्वंद्व से पहले जब राम थक गए, तो अगस्त्य युद्ध के मैदान में उतरे।",
 "df029a93": "उन्होंने आदित्य हृदयम् सिखाया — सूर्य का एक स्तोत्र, जो सब देवताओं के पीछे का प्रकाश है।",
 "06f1ff55": "राम ने तीन बार इसका पाठ किया, धनुष उठाया, और रावण का वध किया।",
 "e447f3fb": "अपने सबसे कठिन युद्ध के बीच राम भी थक गए और चिंतित हो गए। जब तुम्हें हार मान लेने का मन करता है, तो तुम्हें फिर से ताक़त किससे मिलती है?",
 "1ccb957d": "दक्षिण के ऋषि",
 "72f3fb5b": "अगस्त्य ने विंध्य पार किया और कभी उत्तर नहीं लौटे। दक्षिण में उन्होंने मलय पहाड़ियों पर अपना घर बनाया — वह पर्वत जिसे तमिल देश पोतियिल कहता है, जिसे आज अगस्त्यमलै, यानी अगस्त्य की पहाड़ी, भी कहते हैं, पश्चिमी घाट के दक्षिणी छोर पर। उनके आसपास पुराने ग्रंथ अपनी कुछ सबसे प्यारी कथाएँ इकट्ठी करते हैं।",
 "7971112e": "ललिता के सहस्र नाम",
 "6d674ff9": "ब्रह्मांड पुराण बताता है कि संसार में घूमते हुए अगस्त्य लोगों को इच्छाओं और दुख में खोया देखकर दुखी हुए। वे कांची गए और तपस्या की, और {hayagriva|हयग्रीव} — विष्णु, ज्ञान के घोड़े के सिर वाले स्वामी के रूप में — प्रकट हुए और उन्हें दिव्य माता {lalita|ललिता त्रिपुरसुंदरी} की कथा और उपासना सिखाई। आख़िर में अगस्त्य ने उनका सबसे गुप्त स्तोत्र माँगा, और हयग्रीव ने उन्हें ललिता सहस्रनाम, उनके हज़ार नाम, सिखाए।",
 "5ee0caaa": "तो हर बार जब कोई तेलुगु परिवार शुक्रवार को ललिता सहस्रनाम का पाठ करता है, तो वह वही शब्द दोहराता है जो हयग्रीव ने अगस्त्य से कहे थे — और लोपामुद्रा को उस उपासना की महान आचार्याओं में से एक के रूप में याद किया जाता है।",
 "f1dffa4e": "धरती का संतुलन",
 "04ac6505": "तमिल परंपरा, कंदपुराणम् में और कई मंदिर-कथाओं में, अगस्त्य के दक्षिण जाने का कारण दूसरी तरह बताती है। जब कैलास पर {shiva|शिव} का {parvati|पार्वती} से विवाह होने वाला था, तो संसार के सारे देवता, ऋषि और प्राणी विवाह देखने उत्तर में इकट्ठे हो गए। उनके भार से धरती झुक गई — उत्तर नीचे धँस गया और दक्षिण ऊपर उठ गया। शिव अगस्त्य की ओर मुड़े: “सिर्फ़ तुम ही इतने भारी हो कि इन सबको संतुलित कर सको। दक्षिण जाओ।”",
 "8d5d206c": "विवाह न देख पाने से अगस्त्य दुखी हुए, पर वे गए, और धरती फिर से बराबर हो गई। उन्हें सांत्वना देने के लिए शिव और पार्वती ने उन्हें दक्षिण में ही अपने विवाह के दर्शन कराए — और तमिलनाडु के कई मंदिर, जैसे पोतियिल पहाड़ियों के पास पापनाशम्, उस जगह का उत्सव मनाते हैं जहाँ ऋषि ने ये दर्शन किए। यह बाद की, दक्षिणी कथा है, संस्कृत महाकाव्यों में नहीं मिलती, पर पूरे तमिल और तेलुगु प्रदेशों में प्यार से सुनी जाती है।",
 "0f3b508f": "कमंडल से निकली नदी",
 "f290e702": "{kaveri|कावेरी} भी उनसे जुड़ी है। कोडगु पहाड़ियों का एक स्थानीय पौराणिक ग्रंथ, कावेरी माहात्म्य, कहता है कि नदी अगस्त्य के कमंडल, उनके जल-पात्र, से निकली; कुछ रूप कहते हैं कि कावेरी खुद उनकी पत्नी थीं। एक लोकप्रिय कथा, जो पुराने ग्रंथ नहीं बल्कि दादी-नानी सुनाती हैं, कहती है कि गणेश ने कौए का रूप लिया, ऋषि के कमंडल पर बैठे और उसे उलट दिया — और कावेरी तलकावेरी से समुद्र तक बहने लगी।",
 "753f0aa6": "तमिल के जनक",
 "d6770c22": "तमिल परंपरा में अगस्त्य — अकत्तियर — को तमिल भाषा के पहले गुरु के रूप में पूजा जाता है। मध्यकाल के टीकाकार कहते हैं कि उन्होंने तमिल का पहला व्याकरण, अकत्तियम्, लिखा, जो अब खो गया है, और उनके शिष्य तोल्काप्पियर ने तोल्काप्पियम् लिखा, जो बचा हुआ सबसे पुराना तमिल व्याकरण है। ये परंपरा के वृत्तांत हैं, ऐसा इतिहास नहीं जिसे सिद्ध किया जा सके — पर ये दिखाते हैं कि दक्षिण ने उत्तर के इस ऋषि को कितनी गहराई से अपना बना लिया।",
 "3597fb6e": "तमिल देश के सिद्ध उन्हें अपनी परंपरा का पहला सिद्ध मानते हैं, और सिद्ध चिकित्सा, योग और रसायन की कई रचनाएँ उनके नाम से हैं। भारत से बहुत दूर भी उनकी पूजा होती थी: पूर्वी जावा के दिनोयो से मिला आठवीं सदी का एक शिलालेख एक राजा द्वारा अगस्त्य का मंदिर बनवाने की बात दर्ज करता है, और उनकी मूर्तियाँ — बड़े पेट वाली, दाढ़ी वाली, हाथ में कमंडल लिए — पूरे जावा के पुराने मंदिरों में खड़ी हैं।",
 "231def62": "पानी को निर्मल करने वाला तारा",
 "e5693777": "और अगस्त्य आकाश में भी हैं। दक्षिण का चमकीला तारा कैनोपस अगस्त्य है, और बरसात के अंत में भोर से पहले उसके उगने की बड़े ध्यान से राह देखी जाती थी। कालिदास रघुवंश में कहते हैं कि घड़े से जन्मे ऋषि के उगने पर शरद ऋतु का पानी निर्मल हो गया — जैसे जिस ऋषि ने कभी गंदला समुद्र पिया था, वही अब हर नदी और तालाब को साफ़ करते हैं। वराहमिहिर की बृहत् संहिता अगस्त्य के उदय पर एक पूरा अध्याय देती है, और पुराण उस समय तारे को दिए जाने वाले जल के अर्पण, अगस्त्य-अर्घ्य, का वर्णन करते हैं।",
 "e4e42a6e": "तो ये हैं अगस्त्य: घड़े से जन्मे, शरीर में छोटे; एक वैदिक द्रष्टा जिन्होंने देवताओं में सुलह कराई; एक पति जो अन्याय का एक सिक्का भी नहीं लेते थे; वातापि को खाने वाले, समुद्र को पीने वाले, जिनके आगे पर्वत झुका; घमंडियों के लिए प्रचंड, राम को देने वाले, सूर्य-स्तोत्र और माता के हज़ार नामों के गुरु; और वे ऋषि जिन्होंने अपनी प्यारी नगरी छोड़ी, दक्षिण में आए, और उसे हमेशा के लिए अपना घर बना लिया।",
 "a0b264ab": "ब्रह्मांड पुराण, ललितोपाख्यान (हयग्रीव और अगस्त्य; ललिता सहस्रनाम)। तमिल कंदपुराणम् और मंदिर-परंपराएँ (शिव के विवाह पर झुकती धरती) — बाद की दक्षिणी कथाएँ। कावेरी माहात्म्य (स्कंद पुराण से जुड़ा एक क्षेत्रीय पौराणिक ग्रंथ); कौए की कथा लोक-परंपरा है। मध्यकालीन तमिल टीकाएँ (अगस्त्य और तोल्काप्पियर)। दिनोयो शिलालेख, पूर्वी जावा। कालिदास, रघुवंश, सर्ग 4 (शरद का पानी); वराहमिहिर, बृहत् संहिता (अगस्त्य का उदय)।",
 "d5d70cf9": "{hayagriva|हयग्रीव} ने कांची में अगस्त्य को ललिता सहस्रनाम सिखाया।",
 "80ebb5fa": "दक्षिणी परंपरा कहती है कि उन्होंने शिव के विवाह पर धरती को संतुलित किया और {kaveri|कावेरी} उनके कमंडल से बही।",
 "3b26aacc": "तमिल देश उन्हें तमिल का जनक मानता है, और कैनोपस तारा अगस्त्य है।",
 "4d6e8c20": "अगस्त्य उत्तर से आए, फिर भी दक्षिण उन्हें अपना ही मानकर प्यार करता है। कोई नया आने वाला किसी नई जगह का सचमुच अपना कैसे बन जाता है?",
 "ae9e3b6e": "लोपामुद्रा",
 "cdff84e0": "अगस्त्य की पत्नी, विदर्भ की राजकुमारी। वे खुद भी एक द्रष्टा हैं: ऋग्वेद का एक सूक्त (1.179) उनके वचन धारण करता है।",
 "2015eb5b": "मरुत",
 "5aeabc25": "इल्वल",
 "0489dd86": "एक धनी और क्रूर दैत्य, जो अपने भाई वातापि की मदद से ब्राह्मण अतिथियों को मारता था।",
 "b18e0747": "वातापि",
 "068d8430": "इल्वल का भाई, जो बकरा या मेढ़ा बन सकता था, पकाया और खाया जा सकता था, और फिर ज़िंदा हो जाता था — जब तक उसका सामना अगस्त्य से नहीं हुआ।",
 "3c78148a": "श्रुतर्वा",
 "beb6bcf0": "एक न्यायप्रिय राजा, जिनके पास अगस्त्य धन माँगने गए।",
 "03ee2585": "ब्रध्नाश्व",
 "ef947531": "त्रसदस्यु",
 "aa6b520d": "इक्ष्वाकु वंश के एक राजा, पुरुकुत्स के पुत्र, जिनकी उदारता की ऋग्वेद में प्रशंसा है।",
 "cc0455c2": "दृढस्यु (इध्मवाह)",
 "30d434e0": "विंध्य",
 "4750ff72": "भारत के बीच फैली पर्वतमाला, जो घमंड में बढ़ गई और अगस्त्य के आगे झुक गई।",
 "037b9ca7": "सूर्य",
 "0e0f1b79": "सूर्य देव, जो तीनों लोकों को प्रकाश देते हैं।",
 "bf9d1109": "कालकेय",
 "702ceaaa": "दानवों का एक क्रूर कुल, जो समुद्र में छिपकर रात को आश्रमों पर हमला करता था।",
 "a7f50892": "वृत्र",
 "b4973e62": "साँप जैसा महान असुर, जिसने पानी को रोक रखा था; इंद्र ने उसे मारा।",
 "c9dfe77b": "नहुष",
 "6b960831": "चंद्रवंश के एक महान राजा, ययाति के पिता, जो कुछ समय के लिए स्वर्ग के राजा बने और घमंड के कारण गिरे।",
 "a45684a0": "शची",
 "cf17f4fe": "इंद्र की रानी, जिन्हें इंद्राणी या पौलोमी भी कहते हैं।",
 "5057b468": "युधिष्ठिर",
 "70e5788a": "पांडवों में सबसे बड़े, धर्म के पुत्र, जो कभी झूठ न बोलने के लिए प्रसिद्ध हैं।",
 "40d260ee": "लोमश",
 "a2206c99": "एक ऋषि, जिन्होंने वन में पांडवों को तीर्थयात्रा कराई और उन्हें पवित्र स्थानों की कथाएँ सुनाईं।",
 "bcb244bb": "भीम",
 "b7129b39": "दूसरे पांडव, वायु के पुत्र, भाइयों में सबसे बलवान।",
 "8bb0c629": "इंद्रद्युम्न",
 "eb74a931": "एक पांड्य राजा और विष्णु के भक्त, जिन्हें अगस्त्य ने हाथी गजेंद्र बनने का श्राप दिया।",
 "bbe9e37e": "मणिमान",
 "1f6ab463": "एक यक्ष, कुबेर का मित्र, जिसने अगस्त्य का अपमान किया।",
 "ca2ebbab": "सुंद",
 "b1a8a724": "ताड़का का पति, जो अगस्त्य के श्राप से मारा गया।",
 "9d032164": "श्वेत",
 "648f033f": "शंबूक",
 "a6dfe389": "उत्तर कांड का एक तपस्वी, जिसे राम ने मारा — रामायण की सबसे कठिन घटनाओं में से एक।",
 "dc325ef5": "हयग्रीव",
 "0aa17bc7": "घोड़े के सिर वाले रूप में विष्णु, ज्ञान के स्वामी, जिन्होंने अगस्त्य को ललिता सहस्रनाम सिखाया।",
 "535205c7": "ललिता त्रिपुरसुंदरी",
 "b072d0b6": "तीनों लोकों की सुंदर रानी के रूप में दिव्य माता।",
 "71b1f6cf": "कावेरी",
 "74ca25fc": "दक्षिण की महान पवित्र नदी, जिसके बारे में परंपरा कहती है कि वह अगस्त्य के कमंडल से बही।",
 "47d02062": "नारद",
 "e074a4b0": "एक देवर्षि, जो अपनी वीणा बजाते और नारायण का नाम गाते हुए सभी लोकों में घूमते हैं। उन्हें पता रहता है कि हर जगह क्या हो रहा है।",
 "d721984b": "विष्णु",
 "261d40ad": "ब्रह्मांड के रक्षक, जो महान गरुड़ पर सवारी करते हैं और शंख, चक्र और गदा धारण करते हैं। जब भी धर्म ख़तरे में होता है, वे धरती पर जन्म लेते हैं।",
 "ecbcc245": "भगीरथ",
 "bffc08ff": "सगर के परपोते के पुत्र, जिनकी अथक तपस्या गंगा को स्वर्ग से धरती पर लाई। किसी बहुत बड़े प्रयास को आज भी “भगीरथ प्रयत्न” कहा जाता है।",
 "2a6d19ff": "बृहस्पति",
 "84190fbf": "ऋषि अंगिरा के पुत्र और देवताओं के गुरु — शुक्राचार्य के बड़े प्रतिद्वंद्वी। वे बृहस्पति ग्रह हैं।",
 "9f68faff": "भृगु",
 "31727e45": "ब्रह्मा के मानस पुत्रों में से एक और महान ऋषि, शुक्राचार्य के पिता और भार्गव वंश के संस्थापक।",
 "f7668bd3": "कुबेर",
 "35fdef91": "धन के देवता, यक्षों के राजा, और शिव के मित्र।",
 "de40d4ca": "मारीच",
 "b12a9575": "ताड़का का पुत्र, माया में निपुण एक राक्षस। इसे याद रखना — यह कथा में आगे फिर आएगा।",
 "77108ca2": "सुतीक्ष्ण",
 "422aed96": "बड़ी तपस्या वाले एक ऋषि, अगस्त्य के शिष्य, जिन्होंने वन में दो बार राम का स्वागत किया।",
 "81e2fd5c": "रावण",
 "71bd8667": "राक्षसों का दस सिर वाला राजा, लंका का शासक। बड़ा विद्वान और योद्धा, पर घमंडी और क्रूर, उसने देवताओं और ऋषियों दोनों को सताया।",
 "12e96da2": "हनुमान",
 "cc405848": "वायु देव के पुत्र — वानरों में सबसे बलवान और सबसे बुद्धिमान, और राम के सबसे बड़े भक्त।",
 "a8955c5a": "पार्वती",
 "4d2bd384": "शिव की पत्नी, जगन्माता।",
});
